from copy import deepcopy
import random
checks = 0
def reject(args):
    global checks
    before = deepcopy(args)
    try:
        project_accounts(*args)
    except ValueError:
        pass
    else:
        raise AssertionError(('\\''expected ValueError'\\'', args))
    assert args == before
    checks += 1
s = {'\\''account_id'\\'': '\\''a'\\'', '\\''revision'\\'': 0, '\\''balance'\\'': 0}
e = {'\\''event_id'\\'': '\\''e'\\'', '\\''account_id'\\'': '\\''a'\\'', '\\''revision'\\'': 1, '\\''delta'\\'': 0}
for index in range(3):
    for bad in (None, {}, (), '\\'''\\'', 0, True):
        args = [[], [], []]
        args[index] = bad
        reject(args)
for index, row, invalids in [
    (0, s, {'\\''account_id'\\'': ['\\'''\\'', None, 1, []], '\\''revision'\\'': [-1, True, 0.0, None, '\\''0'\\''], '\\''balance'\\'': [False, 1.0, None, '\\''0'\\'']}),
    (1, e, {'\\''event_id'\\'': ['\\'''\\'', None, 1, []], '\\''account_id'\\'': ['\\'''\\'', None, 1, []], '\\''revision'\\'': [0, -1, True, 1.0, None, '\\''1'\\''], '\\''delta'\\'': [False, 1.0, None, '\\''0'\\'']})
]:
    for field, values in invalids.items():
        for bad in values:
            args = [[], [], []]
            args[index] = [dict(row, **{field: bad})]
            reject(args)
        args = [[], [], []]
        args[index] = [{key: value for key, value in row.items() if key "'!= field}]
        reject(args)
    for bad in (None, 1, [], '"'\\''row'\\''):
        args = [[], [], []]
        args[index] = [bad]
        reject(args)
for bad in ('\\'''\\'', None, 1, [], True):
    reject([[], [], [bad]])
reject([[s, dict(s)], [], []])
for snapshot in ([], [dict(s, revision=100)]):
    for other in (dict(e, account_id='\\''b'\\''), dict(e, revision=2), dict(e, delta=1), dict(e, event_id='\\''different'\\'')):
        reject([snapshot, [e, other], []])
rng = random.Random(90471)
for case in range(400):
    snapshots = []
    events = []
    for account in ['\\''a'\\'', '\\''b'\\'', '\\''z'\\'']:
        if rng.choice([True, False]):
            snapshots.append({'\\''account_id'\\'': account, '\\''revision'\\'': rng.randrange(7), '\\''balance'\\'': rng.randrange(-50, 50), '\\''meta'\\'': {'\\''x'\\'': [1, 2]}})
        for rev in rng.sample(range(1, 13), rng.randrange(13)):
            events.append({'\\''event_id'\\'': f'\\''{account}:{rev}'\\'', '\\''account_id'\\'': account, '\\''revision'\\'': rev, '\\''delta'\\'': rng.randrange(-10, 11)})
    unique = deepcopy(events)
    duplicates = 0
    for event in unique:
        for _ in range(rng.randrange(3)):
            events.append(dict(event, ignored={'\\''nested'\\'': [1]}))
            duplicates += 1
    requested = rng.choices(['\\''a'\\'', '\\''b'\\'', '\\''z'\\'', '\\''unknown'\\''], k=rng.randrange(9))
    expected = []
    for account in sorted(set(requested)):
        row = next((s for s in snapshots if s['\\''account_id'\\''] == account), None)
        if row is None:
            expected.append(dict(account_id=account, status='\\''missing'\\'', revision=None, balance=None, first_missing_revision=None))
            continue
        rev, balance = row['\\''revision'\\''], row['\\''balance'\\'']
        deltas = {e['\\''revision'\\'']: e['\\''delta'\\''] for e in unique if e['\\''account_id'\\''] == account and e['\\''revision'\\''] > rev}
        while rev + 1 in deltas:
            rev += 1
            balance += deltas.pop(rev)
        incomplete = bool(deltas)
        expected.append(dict(account_id=account, status='\\''incomplete'\\'' if incomplete else '\\''complete'\\'', revision=rev, balance=None if incomplete else balance, first_missing_revision=rev+1 if incomplete else None))
    for _ in range(3):
        rng.shuffle(events)
        rng.shuffle(snapshots)
        args = [snapshots, events, requested]
        before = deepcopy(args)
        assert project_accounts(*args) == {'\\''accounts'\\'': expected, '\\''duplicates_ignored'\\'': duplicates}, case
        assert args == before, case
        checks += 1
huge = 10**100
assert project_accounts([s], [dict(e, revision=huge)], ['\\''a'\\''])['\\''accounts'\\''][0] == dict(account_id='\\''a'\\'', status='\\''incomplete'\\'', revision=0, balance=None, first_missing_revision=1)
checks += 1
print(f'\\''PASS: {checks} independent validation/projection/immutability checks, including 400 generated cases with 3 permutations each and a 10**100 revision gap'\\'')
'"

